#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <climits>
#include <cstring>

using namespace std;

struct Coord {
    int r, c;
    Coord(int _r=0, int _c=0): r(_r), c(_c) {}
};

int dr[] = {-1, 0, 0, 1};
int dc[] = {0, -1, 1, 0};

int sizeN, maxT;
char maze[12][12], mazeA[12][12], mazeB[12][12];
int distA[12][12], distB[12][12];

void computeDistA(const Coord& start) {
    memset(distA, -1, sizeof(distA));
    distA[start.r][start.c] = 0;
    queue<Coord> q;
    q.push(start);
    while (!q.empty()) {
        Coord p = q.front(); q.pop();
        for (int k=0; k<4; ++k) {
            Coord np(p.r + dr[k], p.c + dc[k]);
            if (maze[np.r][np.c] != '.') continue;
            if (distA[np.r][np.c] < 0) {
                distA[np.r][np.c] = distA[p.r][p.c] + 1;
                q.push(np);
            }
        }
    }
}

void computeDistB(const Coord& start) {
    memset(distB, -1, sizeof(distB));
    distB[start.r][start.c] = 0;
    queue<Coord> q;
    q.push(start);
    while (!q.empty()) {
        Coord p = q.front(); q.pop();
        if (distA[p.r][p.c] >= 0 && distB[p.r][p.c] >= distA[p.r][p.c]) continue;
        for (int k=0; k<4; ++k) {
            Coord np(p.r + dr[k], p.c + dc[k]);
            if (maze[np.r][np.c] != '.') continue;
            if (distB[np.r][np.c] < 0) {
                if (distA[np.r][np.c] >= 0 && distA[np.r][np.c] < distB[p.r][p.c] + 1) continue;
                distB[np.r][np.c] = distB[p.r][p.c] + 1;
                q.push(np);
            }
        }
    }
}

struct FlowNetwork {
    int n;
    vector<vector<int>> capacity, flow;
    vector<int> parent, level;

    FlowNetwork(int size): n(size), capacity(size, vector<int>(size,0)), flow(size, vector<int>(size,0)), parent(size), level(size) {}

    void addEdge(int u, int v, int c) {
        capacity[u][v] += c;
    }

    int bfs(int s, int t, vector<int>& path) {
        fill(parent.begin(), parent.end(), -1);
        fill(level.begin(), level.end(), -1);
        level[s]=0;
        queue<int> q;
        q.push(s);
        while (!q.empty()) {
            int u=q.front(); q.pop();
            if (u==t) {
                int minCap=INT_MAX;
                for (int v=t; v!=s; v=parent[v]) {
                    minCap = min(minCap, capacity[parent[v]][v]-flow[parent[v]][v]);
                }
                path.clear();
                for (int v=t; v!=s; v=parent[v]) path.push_back(v);
                path.push_back(s);
                reverse(path.begin(), path.end());
                return minCap;
            }
            for (int v=0; v<n; ++v) {
                if (parent[v]<0 && capacity[u][v]-flow[u][v]>0) {
                    parent[v]=u;
                    level[v]=level[u]+1;
                    q.push(v);
                }
            }
        }
        return 0;
    }

    int maxFlow(int s, int t) {
        int totalFlow=0;
        vector<int> p;
        while (int push=bfs(s,t,p)) {
            for (size_t i=0; i+1<p.size(); ++i) {
                int u=p[i], v=p[i+1];
                flow[u][v]+=push;
                flow[v][u]-=push;
            }
            totalFlow+=push;
        }
        return totalFlow;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> sizeN >> maxT;
    memset(mazeA, '#', sizeof(mazeA));
    for (int r=1; r<=sizeN; ++r) {
        cin >> (mazeA[r]+1);
        mazeA[r][sizeN+1]='#';
    }
    memset(mazeB, '#', sizeof(mazeB));
    for (int r=1; r<=sizeN; ++r) {
        cin >> (mazeB[r]+1);
        mazeB[r][sizeN+1]='#';
    }
    memset(maze, '#', sizeof(maze));
    vector<Coord> scientists, capsules;
    Coord z;
    for (int r=1; r<=sizeN; ++r) {
        for (int c=1; c<=sizeN; ++c) {
            if (isdigit(mazeA[r][c])) {
                if (mazeA[r][c]>'0') scientists.emplace_back(r,c);
                maze[r][c]='.';
            } else if (mazeA[r][c]=='Z') {
                z=Coord(r,c);
                maze[r][c]='.';
            }
            if (isdigit(mazeB[r][c]) && mazeB[r][c]>'0') {
                capsules.emplace_back(r,c);
            }
        }
    }
    computeDistA(z);
    int s=0;
    int t= (int)scientists.size() + (int)capsules.size() + 1;
    FlowNetwork fn(t+1);
    for (int i=0; i<(int)scientists.size(); ++i) {
        fn.addEdge(s, i+1, mazeA[scientists[i].r][scientists[i].c]-'0');
    }
    for (int j=0; j<(int)capsules.size(); ++j) {
        fn.addEdge((int)scientists.size()+j+1, t, mazeB[capsules[j].r][capsules[j].c]-'0');
    }
    for (int i=0; i<(int)scientists.size(); ++i) {
        computeDistB(scientists[i]);
        for (int j=0; j<(int)capsules.size(); ++j) {
            if (distB[capsules[j].r][capsules[j].c]>=0 && distB[capsules[j].r][capsules[j].c]<=maxT)
                fn.addEdge(i+1, (int)scientists.size()+j+1, INT_MAX);
        }
    }
    int answer=fn.maxFlow(s,t);
    cout << answer << "\n";
    return 0;
}
